import{G as e,K as t,at as n,n as r}from"./chunks/framework.Cv3A6T7g.js";var i=JSON.parse(`{"title":"Rate limiter","description":"","frontmatter":{},"headers":[],"relativePath":"config/api/rate-limiter.md","filePath":"config/api/rate-limiter.md"}`),a={name:`config/api/rate-limiter.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="rate-limiter" tabindex="-1">Rate limiter <a class="header-anchor" href="#rate-limiter" aria-label="Permalink to “Rate limiter”">​</a></h1><p>Path: <code>apps/api/src/config/rate-limiter.ts</code></p><p><a href="https://redis.io" target="_blank" rel="noreferrer">Redis</a> is used as rate-limiter store driver.</p><p>Redis is also used for other parts of system (cache, queue, session), they have separate connection settings, so they can be configured independently if needed.</p><div class="tip custom-block"><p class="custom-block-title">Rate limiter time window definition</p><p>Time window to track the requests is defined as <code>ms-formatted</code> string, see <a href="https://github.com/vercel/ms" target="_blank" rel="noreferrer">ms</a> for more information.</p></div><h2 id="redis-instance" tabindex="-1">Redis instance <a class="header-anchor" href="#redis-instance" aria-label="Permalink to “Redis instance”">​</a></h2><h3 id="url" tabindex="-1">URL <a class="header-anchor" href="#url" aria-label="Permalink to “URL”">​</a></h3><ul><li>object-path: <code>redis.url</code></li><li>dotenv var: <code>RATE_LIMITER_REDIS_URL | REDIS_URL</code></li><li>type: <code>string</code></li><li>default: <code>undefined</code></li></ul><h3 id="host" tabindex="-1">Host <a class="header-anchor" href="#host" aria-label="Permalink to “Host”">​</a></h3><ul><li>object-path: <code>redis.host</code></li><li>dotenv var: <code>RATE_LIMITER_REDIS_HOST | REDIS_HOST</code></li><li>type: <code>string</code></li><li>default: <code>&#39;localhost&#39;</code></li></ul><h3 id="port" tabindex="-1">Port <a class="header-anchor" href="#port" aria-label="Permalink to “Port”">​</a></h3><ul><li>object-path: <code>redis.port</code></li><li>dotenv var: <code>RATE_LIMITER_REDIS_PORT | REDIS_PORT</code></li><li>type: <code>number</code></li><li>default: <code>6379</code></li></ul><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to “Database”">​</a></h3><ul><li>object-path: <code>redis.db</code></li><li>dotenv var: <code>RATE_LIMITER_REDIS_DATABASE | REDIS_DATABASE</code></li><li>type: <code>number</code></li><li>default: <code>0</code></li></ul><h3 id="key-prefix" tabindex="-1">Key prefix <a class="header-anchor" href="#key-prefix" aria-label="Permalink to “Key prefix”">​</a></h3><ul><li>object-path: <code>redis.keyPrefix</code></li><li>dotenv var: <code>RATE_LIMITER_REDIS_PREFIX</code></li><li>type: <code>string</code></li><li>default: <code>&#39;it24:rate-limiter:&#39;</code></li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><p>Each request is checked against every limit that applies to it, and is rejected with <code>429 Too Many Requests</code> when any of them is exceeded.</p><div class="warning custom-block"><p class="custom-block-title">Client IP address</p><p>Limits counted per client IP address rely on <code>PROXY</code> being set correctly when the API runs behind a reverse proxy, see <a href="./security">security settings</a>. If it is not set, all requests appear to come from the proxy address.</p></div><h3 id="generic-anonymous" tabindex="-1">Generic - anonymous <a class="header-anchor" href="#generic-anonymous" aria-label="Permalink to “Generic - anonymous”">​</a></h3><p>All <code>/api</code> requests without a valid access token, counted per client IP address.</p><p>Counted: all requests.</p><h4 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.genericAnonymous.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_GENERIC_ANONYMOUS_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;5m&#39;</code></li></ul><h4 id="limit" tabindex="-1">Limit <a class="header-anchor" href="#limit" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.genericAnonymous.limit</code></li><li>dotenv var: <code>RATE_LIMITER_GENERIC_ANONYMOUS_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>600</code></li></ul><h3 id="generic-survey-user" tabindex="-1">Generic - survey user <a class="header-anchor" href="#generic-survey-user" aria-label="Permalink to “Generic - survey user”">​</a></h3><p>All <code>/api</code> requests with a valid survey access token, counted per user. These requests are not counted against the client IP address, so respondents sharing one external IP address do not share a limit.</p><p>Counted: all requests.</p><h4 id="window-1" tabindex="-1">Window <a class="header-anchor" href="#window-1" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.genericSurveyUser.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_GENERIC_SURVEY_USER_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;5m&#39;</code></li></ul><h4 id="limit-1" tabindex="-1">Limit <a class="header-anchor" href="#limit-1" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.genericSurveyUser.limit</code></li><li>dotenv var: <code>RATE_LIMITER_GENERIC_SURVEY_USER_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>600</code></li></ul><h3 id="generic-admin-user" tabindex="-1">Generic - admin user <a class="header-anchor" href="#generic-admin-user" aria-label="Permalink to “Generic - admin user”">​</a></h3><p>All <code>/api</code> requests with a valid admin access token (including personal access tokens), counted per user.</p><p>Counted: all requests.</p><h4 id="window-2" tabindex="-1">Window <a class="header-anchor" href="#window-2" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.genericAdminUser.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_GENERIC_ADMIN_USER_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;5m&#39;</code></li></ul><h4 id="limit-2" tabindex="-1">Limit <a class="header-anchor" href="#limit-2" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.genericAdminUser.limit</code></li><li>dotenv var: <code>RATE_LIMITER_GENERIC_ADMIN_USER_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>1200</code></li></ul><h3 id="login-account-ip" tabindex="-1">Login - account &amp; IP <a class="header-anchor" href="#login-account-ip" aria-label="Permalink to “Login - account &amp; IP”">​</a></h3><p>Email (<code>/api/auth/login</code>, <code>/api/admin/auth/login</code>) and alias (<code>/api/auth/login/alias</code>) logins, counted per account and client IP address. Does not apply to requests with a valid device cookie.</p><p>Counted: failed requests.</p><h4 id="window-3" tabindex="-1">Window <a class="header-anchor" href="#window-3" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.loginAccountIp.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_ACCOUNT_IP_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;15m&#39;</code></li></ul><h4 id="limit-3" tabindex="-1">Limit <a class="header-anchor" href="#limit-3" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.loginAccountIp.limit</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_ACCOUNT_IP_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>5</code></li></ul><h3 id="login-account" tabindex="-1">Login - account <a class="header-anchor" href="#login-account" aria-label="Permalink to “Login - account”">​</a></h3><p>Email and alias logins, counted per account regardless of client IP address. Backstop against password guessing from many addresses. When exceeded, logins to the account are blocked from all IP addresses, except from devices with a valid device cookie, to which this limit does not apply.</p><p>Counted: failed requests.</p><h4 id="window-4" tabindex="-1">Window <a class="header-anchor" href="#window-4" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.loginAccount.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_ACCOUNT_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;15m&#39;</code></li></ul><h4 id="limit-4" tabindex="-1">Limit <a class="header-anchor" href="#limit-4" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.loginAccount.limit</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_ACCOUNT_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>50</code></li></ul><h3 id="login-ip" tabindex="-1">Login - IP <a class="header-anchor" href="#login-ip" aria-label="Permalink to “Login - IP”">​</a></h3><p>All logins, including URL token logins (<code>/api/auth/login/token</code>), counted per client IP address across all accounts. Does not apply to requests with a valid device cookie.</p><p>Counted: failed requests.</p><h4 id="window-5" tabindex="-1">Window <a class="header-anchor" href="#window-5" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.loginIp.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_IP_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;15m&#39;</code></li></ul><h4 id="limit-5" tabindex="-1">Limit <a class="header-anchor" href="#limit-5" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.loginIp.limit</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_IP_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>100</code></li></ul><h3 id="login-device" tabindex="-1">Login - device <a class="header-anchor" href="#login-device" aria-label="Permalink to “Login - device”">​</a></h3><p>Email and alias logins with a valid device cookie, counted per device cookie. When the limit is exceeded, the device cookie is ignored and the account and IP limits above apply instead.</p><p>Counted: failed requests.</p><h4 id="window-6" tabindex="-1">Window <a class="header-anchor" href="#window-6" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.loginDevice.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_DEVICE_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;15m&#39;</code></li></ul><h4 id="limit-6" tabindex="-1">Limit <a class="header-anchor" href="#limit-6" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.loginDevice.limit</code></li><li>dotenv var: <code>RATE_LIMITER_LOGIN_DEVICE_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>10</code></li></ul><h3 id="password-reset-account" tabindex="-1">Password reset - account <a class="header-anchor" href="#password-reset-account" aria-label="Permalink to “Password reset - account”">​</a></h3><p>Password reset requests (<code>/api/password</code>), counted per email address.</p><p>Counted: successful requests.</p><h4 id="window-7" tabindex="-1">Window <a class="header-anchor" href="#window-7" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.passwordResetAccount.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_PASSWORD_RESET_ACCOUNT_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;1h&#39;</code></li></ul><h4 id="limit-7" tabindex="-1">Limit <a class="header-anchor" href="#limit-7" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.passwordResetAccount.limit</code></li><li>dotenv var: <code>RATE_LIMITER_PASSWORD_RESET_ACCOUNT_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>3</code></li></ul><h3 id="password-reset-ip" tabindex="-1">Password reset - IP <a class="header-anchor" href="#password-reset-ip" aria-label="Permalink to “Password reset - IP”">​</a></h3><p>Password reset requests (<code>/api/password</code>), counted per client IP address.</p><p>Counted: all requests.</p><h4 id="window-8" tabindex="-1">Window <a class="header-anchor" href="#window-8" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.passwordResetIp.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_PASSWORD_RESET_IP_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;1h&#39;</code></li></ul><h4 id="limit-8" tabindex="-1">Limit <a class="header-anchor" href="#limit-8" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.passwordResetIp.limit</code></li><li>dotenv var: <code>RATE_LIMITER_PASSWORD_RESET_IP_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>20</code></li></ul><h3 id="email-verification" tabindex="-1">Email verification <a class="header-anchor" href="#email-verification" aria-label="Permalink to “Email verification”">​</a></h3><p>Email verification requests (<code>/api/admin/user/verify</code>), counted per user.</p><p>Counted: successful requests.</p><h4 id="window-9" tabindex="-1">Window <a class="header-anchor" href="#window-9" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.verify.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_VERIFY_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;5m&#39;</code></li></ul><h4 id="limit-9" tabindex="-1">Limit <a class="header-anchor" href="#limit-9" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.verify.limit</code></li><li>dotenv var: <code>RATE_LIMITER_VERIFY_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>1</code></li></ul><h3 id="mfa-verification" tabindex="-1">MFA verification <a class="header-anchor" href="#mfa-verification" aria-label="Permalink to “MFA verification”">​</a></h3><p>Admin MFA verification (<code>/api/admin/auth/verify</code>), counted per user the session&#39;s MFA challenge was issued for, regardless of client IP address. Each challenge allows a single attempt, but a successful password login issues a new challenge without counting towards the login limits, so this limit is what restricts MFA code guessing by someone who knows the password. When exceeded, the user cannot complete MFA from any client until the window expires.</p><p>Counted: failed requests.</p><h4 id="window-10" tabindex="-1">Window <a class="header-anchor" href="#window-10" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.mfaVerify.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_MFA_VERIFY_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;15m&#39;</code></li></ul><h4 id="limit-10" tabindex="-1">Limit <a class="header-anchor" href="#limit-10" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.mfaVerify.limit</code></li><li>dotenv var: <code>RATE_LIMITER_MFA_VERIFY_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>5</code></li></ul><h3 id="generate-user-survey-ip" tabindex="-1">Generate user - survey &amp; IP <a class="header-anchor" href="#generate-user-survey-ip" aria-label="Permalink to “Generate user - survey &amp; IP”">​</a></h3><p>User generation (<code>/api/surveys/:slug/generate-user</code>), counted per survey and client IP address.</p><p>Counted: successful requests.</p><h4 id="window-11" tabindex="-1">Window <a class="header-anchor" href="#window-11" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.generateUserSurveyIp.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_GENERATE_USER_SURVEY_IP_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;5m&#39;</code></li></ul><h4 id="limit-11" tabindex="-1">Limit <a class="header-anchor" href="#limit-11" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.generateUserSurveyIp.limit</code></li><li>dotenv var: <code>RATE_LIMITER_GENERATE_USER_SURVEY_IP_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>30</code></li></ul><h3 id="generate-user-survey" tabindex="-1">Generate user - survey <a class="header-anchor" href="#generate-user-survey" aria-label="Permalink to “Generate user - survey”">​</a></h3><p>User generation (<code>/api/surveys/:slug/generate-user</code>), counted per survey regardless of client IP address. The same limit applies to every survey.</p><p>Counted: successful requests.</p><h4 id="window-12" tabindex="-1">Window <a class="header-anchor" href="#window-12" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.generateUserSurvey.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_GENERATE_USER_SURVEY_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;1h&#39;</code></li></ul><h4 id="limit-12" tabindex="-1">Limit <a class="header-anchor" href="#limit-12" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.generateUserSurvey.limit</code></li><li>dotenv var: <code>RATE_LIMITER_GENERATE_USER_SURVEY_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>240</code></li></ul><h3 id="pdf-outputs" tabindex="-1">PDF outputs <a class="header-anchor" href="#pdf-outputs" aria-label="Permalink to “PDF outputs”">​</a></h3><p>Feedback <code>download</code> and <code>email</code> routes (<code>/api/user/feedback</code>), counted per user.</p><p>Counted: successful requests.</p><h4 id="window-13" tabindex="-1">Window <a class="header-anchor" href="#window-13" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.feedback.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_FEEDBACK_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;1m&#39;</code></li></ul><h4 id="limit-13" tabindex="-1">Limit <a class="header-anchor" href="#limit-13" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.feedback.limit</code></li><li>dotenv var: <code>RATE_LIMITER_FEEDBACK_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>1</code></li></ul><h3 id="survey-feedback-ratings" tabindex="-1">Survey / feedback ratings <a class="header-anchor" href="#survey-feedback-ratings" aria-label="Permalink to “Survey / feedback ratings”">​</a></h3><p>Ratings (<code>/api/surveys/:slug/rating</code>), counted per user.</p><p>Counted: successful requests.</p><h4 id="window-14" tabindex="-1">Window <a class="header-anchor" href="#window-14" aria-label="Permalink to “Window”">​</a></h4><ul><li>object-path: <code>limits.rating.windowMs</code></li><li>dotenv var: <code>RATE_LIMITER_RATING_WINDOW</code></li><li>type: <code>string</code></li><li>default: <code>&#39;15m&#39;</code></li></ul><h4 id="limit-14" tabindex="-1">Limit <a class="header-anchor" href="#limit-14" aria-label="Permalink to “Limit”">​</a></h4><ul><li>object-path: <code>limits.rating.limit</code></li><li>dotenv var: <code>RATE_LIMITER_RATING_LIMIT</code></li><li>type: <code>number</code></li><li>default: <code>1</code></li></ul><h2 id="device-cookie" tabindex="-1">Device cookie <a class="header-anchor" href="#device-cookie" aria-label="Permalink to “Device cookie”">​</a></h2><p>After a fully completed login (including MFA), the API sets a device cookie (<code>it24a_device</code> for admin, <code>it24s_device</code> for survey). It grants no access by itself. On later logins to the same account from the same browser, it replaces the account and IP login limits with the device limit, so that failed attempts by others cannot lock the user out. The cookie uses the same path, <code>SameSite</code> and <code>Secure</code> settings as the refresh token cookie of the respective frontend.</p><h3 id="lifetime" tabindex="-1">Lifetime <a class="header-anchor" href="#lifetime" aria-label="Permalink to “Lifetime”">​</a></h3><ul><li>object-path: <code>deviceCookie.maxAge</code></li><li>dotenv var: <code>DEVICE_COOKIE_LIFETIME</code></li><li>type: <code>string</code></li><li>default: <code>&#39;90d&#39;</code></li></ul><h3 id="max-entries" tabindex="-1">Max entries <a class="header-anchor" href="#max-entries" aria-label="Permalink to “Max entries”">​</a></h3><p>Maximum number of accounts remembered by one browser. The oldest entry is replaced when the limit is reached.</p><ul><li>object-path: <code>deviceCookie.maxEntries</code></li><li>dotenv var: <code>DEVICE_COOKIE_MAX_ENTRIES</code></li><li>type: <code>number</code></li><li>default: <code>5</code></li></ul><h2 id="removed-settings" tabindex="-1">Removed settings <a class="header-anchor" href="#removed-settings" aria-label="Permalink to “Removed settings”">​</a></h2><p>The API refuses to start if any of these variables are set:</p><table tabindex="0"><thead><tr><th>Removed</th><th>Replaced by</th></tr></thead><tbody><tr><td><code>RATE_LIMITER_GENERIC_WINDOW</code>, <code>RATE_LIMITER_GENERIC_LIMIT</code></td><td><code>RATE_LIMITER_GENERIC_ANONYMOUS_*</code>, <code>RATE_LIMITER_GENERIC_SURVEY_USER_*</code>, <code>RATE_LIMITER_GENERIC_ADMIN_USER_*</code></td></tr><tr><td><code>RATE_LIMITER_LOGIN_WINDOW</code>, <code>RATE_LIMITER_LOGIN_LIMIT</code></td><td><code>RATE_LIMITER_LOGIN_ACCOUNT_IP_*</code>, <code>RATE_LIMITER_LOGIN_ACCOUNT_*</code>, <code>RATE_LIMITER_LOGIN_IP_*</code>, <code>RATE_LIMITER_LOGIN_DEVICE_*</code></td></tr><tr><td><code>RATE_LIMITER_PASSWORD_WINDOW</code>, <code>RATE_LIMITER_PASSWORD_LIMIT</code></td><td><code>RATE_LIMITER_PASSWORD_RESET_ACCOUNT_*</code>, <code>RATE_LIMITER_PASSWORD_RESET_IP_*</code></td></tr><tr><td><code>RATE_LIMITER_GEN_USER_WINDOW</code>, <code>RATE_LIMITER_GEN_USER_LIMIT</code></td><td><code>RATE_LIMITER_GENERATE_USER_SURVEY_IP_*</code>, <code>RATE_LIMITER_GENERATE_USER_SURVEY_*</code></td></tr></tbody></table>`,134)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};